import {useEffect} from 'react';

// While any sheet, drum or dialog is open the page under it stays still.
// Safari ignores overflow alone for touch scrolling, so stray touch moves are cancelled too,
// except inside the overlay's own scrolling parts and its fields.
let locks=0,saved=null;
const stray=event=>{if(event.touches?.length>1)return;if(!event.target.closest?.('[data-scroll-allow],.m-modal-body,.m-menu-scroll,input,textarea,select'))event.preventDefault();};
function lock(){
  if(locks++)return;
  const html=document.documentElement,body=document.body;
  saved={html:html.style.overflow,body:body.style.overflow,overscroll:html.style.overscrollBehavior};
  html.style.overflow='hidden';body.style.overflow='hidden';html.style.overscrollBehavior='none';
  document.addEventListener('touchmove',stray,{passive:false});
}
function unlock(){
  if(--locks)return;
  const html=document.documentElement,body=document.body;
  html.style.overflow=saved.html;body.style.overflow=saved.body;html.style.overscrollBehavior=saved.overscroll;
  document.removeEventListener('touchmove',stray);
}
export default function useScrollLock(active=true){
  useEffect(()=>{if(!active)return;lock();return unlock;},[active]);
}
