const DAY=86400000;
const localDay=value=>{const date=new Date(value);return isDayKey(value)?value:Number.isNaN(date.getTime())?null:`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;};
export const isDayKey=value=>typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&!Number.isNaN(Date.parse(value))&&new Date(value).toISOString().slice(0,10)===value;
export function addDays(date,count){return new Date(Date.parse(date)+count*DAY).toISOString().slice(0,10);}
export function dateRange(start,end){if(!isDayKey(start)||!isDayKey(end)||end<start)return [];const days=[];for(let stamp=Date.parse(start);stamp<=Date.parse(end);stamp+=DAY)days.push(new Date(stamp).toISOString().slice(0,10));return days;}
export function dayLabel(date,short=false){return new Intl.DateTimeFormat('ru-RU',{weekday:short?'short':'long',day:'numeric',month:'long'}).format(new Date(`${date}T12:00:00`));}
export function calendarWeeks(start,end){const days=dateRange(start,end);if(!days.length)return [];const offset=(new Date(start).getUTCDay()+6)%7,cells=[...Array(offset).fill(null),...days];while(cells.length%7)cells.push(null);return Array.from({length:cells.length/7},(_,i)=>cells.slice(i*7,i*7+7));}
export function switchScheduleMode(state,mode){
  if((state.scheduleMode||'day')===mode)return state;
  if(mode==='week')return {...state,cardTitle:state.cardTitle==='Расписание на день'?'Расписание на неделю':state.cardTitle,scheduleMode:'week',daySchedule:structuredClone(state.schedule),schedule:structuredClone(state.weekSchedule||[]),weekStart:state.weekStart||state.scheduleDate,weekEnd:state.weekEnd||addDays(state.weekStart||state.scheduleDate,6),offDays:state.offDays||{}};
  return {...state,cardTitle:state.cardTitle==='Расписание на неделю'?'Расписание на день':state.cardTitle,scheduleMode:'day',weekSchedule:structuredClone(state.schedule),schedule:structuredClone(state.daySchedule||[])};
}
// A day template's single dates always show the day it is loaded on; a range of dates keeps its own days.
export function applyScheduleTemplate(state,template,today=new Date()){
  const mode=template.scheduleMode==='week'?'week':'day',next=switchScheduleMode(state,mode),start=template.weekStart||template.scheduleDate||state.scheduleDate;
  const schedule=mode==='day'&&!template.titleInSchedule?titleIntoSchedule(template.schedule,template):template.schedule;
  return {...next,scheduleMode:mode,schedule:structuredClone(schedule).map(item=>({...item,id:crypto.randomUUID(),...(mode==='week'?{dayKey:item.dayKey||start}:item.type==='date'&&!item.endDate?{date:today.toISOString()}:{})})),cardTitle:template.cardTitle||template.name||'',imageUrl:template.imageUrl||null,scheduleDate:template.scheduleDate||state.scheduleDate,scheduleEndDate:template.scheduleEndDate||null,exportWidth:template.exportWidth||state.exportWidth||896,exportHeight:template.exportHeight||null,...(mode==='week'?{weekStart:start,weekEnd:template.weekEnd||addDays(start,6),offDays:structuredClone(template.offDays||{})}:{})};
}
export function reorderSubset(all,subset,id,target,move){const reordered=move(subset,id,target),ids=new Set(subset.map(item=>item.id));let index=0;return all.map(item=>ids.has(item.id)?reordered[index++]:item);}
export function insertDayTemplate(state,template,day){
  const added=structuredClone(template.schedule).filter(item=>item.type!=='date'||item.description?.trim()).map(item=>({...item,id:crypto.randomUUID(),dayKey:day,...(item.type==='date'?{date:day}:{})}));
  return {...state,schedule:[...state.schedule,...added]};
}
export function appendDailyTemplate(state,template){
  const added=structuredClone(template.schedule).filter(item=>item.type!=='date'||item.description?.trim()).map(({dayKey,...item})=>({...item,id:crypto.randomUUID(),...(item.type==='date'?{date:state.scheduleDate}:{})}));
  return {...state,schedule:[...state.schedule,...added]};
}
export function scheduleSnapshot(state,mode,day=state.scheduleDate){
  const next=switchScheduleMode(state,mode);
  if(mode==='week')return structuredClone(next);
  if(state.scheduleMode!=='week')return structuredClone(next);
  return {...structuredClone(next),schedule:structuredClone(state.schedule.filter(item=>item.dayKey===day)).map(({dayKey,...item})=>({...item,...(item.type==='date'?{date:day}:{})})),scheduleDate:day,scheduleEndDate:null};
}
export function clearWeekSchedule(state,scope,day){
  if(scope==='week')return {...state,schedule:[],offDays:{}};
  const offDays={...state.offDays};delete offDays[day];return {...state,schedule:state.schedule.filter(item=>item.dayKey!==day),offDays};
}
// A new session starts today, retaining durations and relative positions of events.
export function restoreScheduleDates(saved,today){
  const oldStart=isDayKey(saved.weekStart)?saved.weekStart:isDayKey(saved.scheduleDate)?saved.scheduleDate:today;
  const span=isDayKey(saved.weekEnd)&&saved.weekEnd>=oldStart?Math.round((Date.parse(saved.weekEnd)-Date.parse(oldStart))/DAY):6;
  const delta=Math.round((Date.parse(today)-Date.parse(oldStart))/DAY);
  const weekly=items=>(items||[]).map(item=>isDayKey(item.dayKey)?{...item,dayKey:addDays(item.dayKey,delta),...(item.type==='date'?{date:addDays(item.dayKey,delta)}:{})}:item);
  // The first date moves to today; its end date keeps the same distance from it.
  const daily=items=>{let changed=false;return (items||[]).map(item=>{if(item.type!=='date'||changed)return item;changed=true;const start=item.date?localDay(item.date):today,end=isDayKey(item.endDate)&&item.endDate>=start?addDays(today,Math.round((Date.parse(item.endDate)-Date.parse(start))/DAY)):undefined;return {...item,date:today,...(end?{endDate:end}:{})};});};
  const second=isDayKey(saved.scheduleDate)&&isDayKey(saved.scheduleEndDate)&&saved.scheduleEndDate>=saved.scheduleDate?addDays(today,Math.round((Date.parse(saved.scheduleEndDate)-Date.parse(saved.scheduleDate))/DAY)):null;
  return {scheduleDate:today,scheduleEndDate:second,weekStart:today,weekEnd:addDays(today,span),offDays:Object.fromEntries(Object.entries(saved.offDays||{}).filter(([day])=>isDayKey(day)).map(([day,off])=>[addDays(day,delta),off])),schedule:saved.scheduleMode==='week'?weekly(saved.schedule):daily(saved.schedule),weekSchedule:weekly(saved.weekSchedule),daySchedule:daily(saved.daySchedule)};
}
export function replaceDayEvents(state,events,day){return insertDayTemplate({...state,schedule:state.schedule.filter(item=>item.dayKey!==day)},{schedule:events},day);}

export const DEFAULT_TITLE_PREFIX='Расписание на';
export function scheduleTitlePrefix(title){return /^Расписание на (день|неделю)$/.test(title||'')?DEFAULT_TITLE_PREFIX:(title??DEFAULT_TITLE_PREFIX);}
export function scheduleTitle(prefix,mode){return prefix===DEFAULT_TITLE_PREFIX?`${prefix} ${mode==='week'?'неделю':'день'}`:prefix;}
export function shortDayLabel(date){return new Intl.DateTimeFormat('ru-RU',{weekday:'short',day:'numeric'}).format(new Date(`${date}T12:00:00`));}

// A day schedule carries its own heading and date as events; older schedules kept them beside the list.
export function titleIntoSchedule(schedule=[],{cardTitle,scheduleDate,scheduleEndDate}={}){
  const items=structuredClone(schedule||[]),head=[],title=scheduleTitlePrefix(cardTitle)===DEFAULT_TITLE_PREFIX?'Расписание на день':(cardTitle||'').trim();
  if(title&&!items.some(item=>item.type==='h1'))head.push({id:crypto.randomUUID(),type:'h1',description:title,time:'',icon:null});
  const end=isDayKey(scheduleEndDate)?scheduleEndDate:null,first=items.find(item=>item.type==='date');
  if(!first)head.push({id:crypto.randomUUID(),type:'date',date:isDayKey(scheduleDate)?scheduleDate:localDay(new Date()),description:'',time:'',icon:null,...(end?{endDate:end}:{})});
  else if(end&&!first.endDate)first.endDate=end;
  return [...head,...items];
}
export function moveTitleIntoSchedule(state){
  if(state.titleInSchedule)return state;
  const day=state.scheduleMode==='week'?'daySchedule':'schedule';
  return {...state,titleInSchedule:true,[day]:titleIntoSchedule(state[day],state)};
}

// A schedule saved in one tap is named after what it shows: its heading and date, or the week's span.
export function scheduleTemplateName(state){
  const short=day=>day.split('-').reverse().slice(0,2).join('.');
  if(state.scheduleMode==='week')return `Неделя ${short(state.weekStart)}–${short(state.weekEnd)}`;
  const heading=state.schedule?.find(item=>item.type==='h1'&&item.description?.trim())?.description.trim(),date=state.schedule?.find(item=>item.type==='date'&&item.date)?.date;
  const day=date?localDay(date):isDayKey(state.scheduleDate)?state.scheduleDate:null;
  return [heading||'День',day&&short(day)].filter(Boolean).join(' · ');
}

