import React,{useState} from 'react';
import {listModels} from '../services/ai.js';
import EditorIcon from './EditorIcon.jsx';

// Gemini in two white groups, as in the rest of the settings: the API keys first (the list of models needs one),
// then the model as a list with a check mark. A model of one's own is typed into the list's last row.
export default function GeminiSettings({config,onChange,perform,busy,onDelete}){
  const [key,setKey]=useState(''),[own,setOwn]=useState(null);
  const models=config.models||[],listed=models.some(entry=>entry.id===config.model);
  const loadModels=()=>perform(async()=>{const result=await listModels({apiKeys:config.apiKeys.map(entry=>entry.key),model:config.model});await onChange({...config,models:result.models});});
  const choose=model=>perform(()=>onChange({...config,model}));
  const addKey=event=>{event.preventDefault();const value=key.trim();if(!value)return;if(config.apiKeys.some(entry=>entry.key===value)){setKey('');return;}perform(async()=>{await onChange({...config,apiKeys:[...config.apiKeys,{id:crypto.randomUUID(),key:value}]});setKey('');});};
  const saveOwn=event=>{event.preventDefault();const value=own.trim().replace(/^models\//,'');if(!/^[a-zA-Z0-9._/-]+$/.test(value))return;perform(async()=>{await onChange({...config,model:value});setOwn(null);});};
  const row=(id,title,detail)=><button type="button" key={id} className="m-ai-row" role="radio" aria-checked={config.model===id} disabled={busy} onClick={()=>choose(id)}><span className="m-ai-row-text"><span>{title}</span>{detail&&<small>{detail}</small>}</span>{config.model===id&&<EditorIcon name="check"/>}</button>;
  return <>
    <section className="m-ai-section">
      <h2>API-ключи</h2>
      <div className="m-ai-group">
        {config.apiKeys.map((entry,index)=><div className="m-ai-row is-static" key={entry.id}><span className="m-ai-row-text"><span>Ключ {index+1}</span><small>••••{entry.key.slice(-4)}</small></span><button type="button" className="m-ai-row-action m-danger" disabled={busy} aria-label={`Удалить API ключ ${index+1}`} onClick={()=>onDelete('Удалить API ключ?','Ключ будет удалён только из этого приложения.',()=>onChange({...config,apiKeys:config.apiKeys.filter(value=>value.id!==entry.id)}))}><EditorIcon name="trash"/></button></div>)}
        <form className="m-ai-row is-input" onSubmit={addKey}><input type="password" autoComplete="off" aria-label="Новый API ключ" placeholder={config.apiKeys.length?'Ещё один ключ':'Вставьте ключ'} value={key} maxLength={300} onChange={event=>setKey(event.target.value)}/><button className="m-ai-row-action is-text" disabled={busy||!key.trim()}>Добавить</button></form>
      </div>
      <p className="m-ai-note">Ключ бесплатно выдаёт Google AI Studio. Несколько ключей используются по очереди, когда у одного кончается лимит.</p>
    </section>
    <section className="m-ai-section">
      <h2>Модель{config.apiKeys.length>0&&<button type="button" className="m-ai-head-action" disabled={busy} onClick={loadModels}>{busy?'Загружаем…':models.length?'Обновить список':'Загрузить список'}</button>}</h2>
      <div className="m-ai-group m-ai-models" role="radiogroup" aria-label="Модель Gemini">
        {!listed&&row(config.model,config.model,models.length?'Своя модель':null)}
        {models.map(entry=>row(entry.id,entry.name,entry.id))}
        {own===null
          ?<button type="button" className="m-ai-row is-muted" disabled={busy} onClick={()=>setOwn(listed?'':config.model)}><span className="m-ai-row-text"><span>Своя модель…</span></span></button>
          :<form className="m-ai-row is-input" onSubmit={saveOwn}><input autoFocus aria-label="Имя модели" placeholder="например, gemini-2.5-pro" value={own} onChange={event=>setOwn(event.target.value)} onKeyDown={event=>{if(event.key==='Escape')setOwn(null);}}/><button className="m-ai-row-action is-text" disabled={busy||!/^[a-zA-Z0-9._/-]+$/.test(own.trim().replace(/^models\//,''))}>Готово</button></form>}
      </div>
      {!config.apiKeys.length&&<p className="m-ai-note">Список моделей появится после добавления ключа.</p>}
    </section>
  </>;
}
