import React from 'react';
import {eventLabel} from '../services/editor.js';

export default function QuickEventTime({item,Icon,onOpen,onTime}){
  const timed=['timed','range','game'].includes(item.type);
  const times=<><span className="m-event-time" data-time-field="time">{item.time}</span>{['range','game'].includes(item.type)&&<span className="m-event-time" data-time-field="endTime">{item.endTime}</span>}</>;
  return <div className={`m-time-hit m-time-static ${['range','game'].includes(item.type)?'is-range':''}`}>
    {timed?<button type="button" data-quick-time className="m-quick-times m-quick-time-button" aria-label={`Изменить время: ${eventLabel(item)}`} onClick={event=>onTime(event.target.closest('[data-time-field]')?.dataset.timeField||'time')}>{times}</button>:<span className="m-quick-times" aria-hidden="true"/>}
    {<button type="button" data-no-drag className="m-event-icon-button" aria-label={`Редактировать значок и запись: ${eventLabel(item)}`} onClick={onOpen}><span className="m-event-icon"><Icon icon={item.icon}/></span></button>}
  </div>;
}
