import {validImageSize} from './image-sizes.js';
import {EVENT_TYPES} from './editor.js';
import {isDayKey} from './week.js';
import {isFolder,validFolderTree} from './template-folders.js';
import {validTranslationRule} from './glossary.js';
const object=value=>value&&typeof value==='object'&&!Array.isArray(value);
const text=value=>typeof value==='string';
const image=value=>value==null||text(value)&&(!value||/^data:image\/[\w.+-]+[;,]/i.test(value)||/^https?:\/\//i.test(value));
const team=value=>object(value)&&text(value.name)&&image(value.image);
const event=value=>object(value)&&Object.hasOwn(EVENT_TYPES,value.type)&&text(value.description??'')&&(!value.dayKey||isDayKey(value.dayKey))&&(!value.homeTeam||team(value.homeTeam))&&(!value.awayTeam||team(value.awayTeam));
const schedule=value=>object(value)&&Array.isArray(value.schedule)&&value.schedule.every(event)&&text(value.name||value.cardTitle||'')&&(!value.scheduleMode||['day','week'].includes(value.scheduleMode))&&(value.scheduleMode!=='week'||isDayKey(value.weekStart)&&isDayKey(value.weekEnd)&&value.weekEnd>=value.weekStart&&value.schedule.every(item=>isDayKey(item.dayKey)))&&(!value.scheduleEndDate||isDayKey(value.scheduleEndDate)&&(!isDayKey(value.scheduleDate)||value.scheduleEndDate>=value.scheduleDate))&&(!value.offDays||object(value.offDays)&&Object.entries(value.offDays).every(([key,off])=>isDayKey(key)&&typeof off==='boolean'));
const rule=value=>validTranslationRule({...value,id:value?.id||'imported'});
const folder=value=>object(value)&&isFolder(value)&&text(value.name)&&value.name.trim().length>0;
const hasParent=value=>value.parentId==null||text(value.parentId);
export function exportTemplates(collections){return JSON.stringify({format:'multischedule-templates',version:1,exportedAt:new Date().toISOString(),...collections},null,2);}
export function parseTemplates(source){
  let data;try{data=JSON.parse(source);}catch{throw Error('Не удалось прочитать JSON. Выберите файл, выгруженный из приложения.');}
  if(!object(data)||data.format!=='multischedule-templates'||data.version!==1)throw Error('Этот файл не является архивом шаблонов MultiSchedule.');
  const checks={events:event,schedules:schedule,translations:rule,teams:team,sizes:validImageSize},result={};
  for(const [key,check] of Object.entries(checks)){
    if(key==='sizes'&&data[key]===undefined)data[key]=[];
    if(!Array.isArray(data[key])||!data[key].every(entry=>(isFolder(entry)?folder(entry):check(entry))&&hasParent(entry)))throw Error('В файле повреждены шаблоны. Данные не загружены.');
    const entries=data[key].map(entry=>({...entry,id:entry.id||crypto.randomUUID()}));
    if(!validFolderTree(entries))throw Error('В файле повреждена структура папок. Данные не загружены.');
    const ids=new Map(entries.map(entry=>[entry.id,crypto.randomUUID()]));
    result[key]=entries.map(entry=>({...entry,id:ids.get(entry.id),...(entry.parentId?{parentId:ids.get(entry.parentId)}:{})}));
  }
  return result;
}
const signature=value=>JSON.stringify(value,(key,entry)=>key==='id'?undefined:object(entry)?Object.fromEntries(Object.entries(entry).sort(([a],[b])=>a.localeCompare(b))):entry);
export function mergeTemplateCollections(current,incoming){
  const merged={};
  for(const key of ['events','schedules','translations','teams','sizes']){
    const normalized=entry=>signature({...entry,parentId:entry.parentId||null});
    const seen=new Map((current[key]||[]).map(entry=>[normalized(entry),entry.id])),mapping=new Map(),pending=[...(incoming[key]||[])];merged[key]=[...(current[key]||[])];
    while(pending.length){let progress=false;
      for(let i=0;i<pending.length;){const source=pending[i];if(source.parentId&&!mapping.has(source.parentId)){i++;continue;}
        const entry=structuredClone({...source,...(source.parentId?{parentId:mapping.get(source.parentId)}:{})}),sig=normalized(entry),existing=seen.get(sig);
        if(existing)mapping.set(source.id,existing);else{merged[key].push(entry);seen.set(sig,entry.id);mapping.set(source.id,entry.id);}pending.splice(i,1);progress=true;
      }
      if(!progress)throw Error('Не удалось восстановить структуру папок.');
    }
  }
  return merged;
}
