import React, { forwardRef } from "react";

// next/image is unnecessary for the local editor: uploaded images stay in-browser.
export default forwardRef(function LocalImage(
  {
    src,
    alt = "",
    fill,
    priority,
    unoptimized,
    quality,
    loader,
    placeholder,
    blurDataURL,
    onLoadingComplete,
    style,
    ...props
  },
  ref,
) {
  return (
    <img
      ref={ref}
      src={typeof src === "object" ? src.src : src}
      alt={alt}
      style={
        fill
          ? {
              position: "absolute",
              inset: 0,
              width: "100%",
              height: "100%",
              ...style,
            }
          : style
      }
      {...props}
    />
  );
});
