import React,{useLayoutEffect,useRef,useState} from 'react';

export default function ExportPreview({renderPreview,sourceRef,width,height}){
  const frame=useRef(null),content=useRef(null),[layout,setLayout]=useState({scale:1,fit:1,natural:300});
  useLayoutEffect(()=>{
    const measure=()=>{const natural=content.current.offsetHeight,scale=frame.current.clientWidth/width,fit=height?Math.min(1,height/Math.max(1,natural)):1;
      setLayout(current=>current.scale===scale&&current.fit===fit&&current.natural===natural?current:{scale,fit,natural});};
    const observer=new ResizeObserver(measure);observer.observe(frame.current);observer.observe(content.current);measure();return()=>observer.disconnect();
  },[width,height]);
  const documentHeight=height||layout.natural;
  return <div className="m-preview-stage" ref={frame} style={{height:documentHeight*layout.scale}} aria-label="Предпросмотр изображения">
    <div className="m-preview-scale" style={{width,transform:`scale(${layout.scale})`}}>
      <div className="m-preview-document" ref={sourceRef} data-fixed-size={height?'true':undefined} style={{width,height:height||'auto',overflow:height?'hidden':'visible',background:'#fff',position:'relative'}} inert>
        <div ref={content} style={{width,transformOrigin:'top center',transform:`scale(${layout.fit})`}}>{renderPreview()}</div>
      </div>
    </div>
  </div>;
}
