import React,{useSyncExternalStore} from 'react';
import {appUpdate,activateServiceWorker,APP_VERSION,SERVICE_WORKER_URL} from '../services/app-update.js';
import {appStorage} from '../services/storage.js';

const useUpdate=()=>useSyncExternalStore(appUpdate.subscribe,appUpdate.getSnapshot);
const apply=()=>appUpdate.apply({storage:appStorage,activate:()=>activateServiceWorker(SERVICE_WORKER_URL),reload:()=>location.reload()});

export default function UpdateNotice(){
  const update=useUpdate();
  if(!['ready','updating'].includes(update.status))return null;
  const busy=update.status==='updating';
  return <div role="status" aria-live="polite" className="m-update-notice">
    <div><strong>{busy?'Обновляем…':'Доступна новая версия'}{!busy&&update.version?` ${update.version}`:''}</strong><span>{update.error||'Ваши расписания и шаблоны сохранятся.'}</span></div>
    {!busy&&<button type="button" className="m-update-apply" onClick={apply}>Обновить</button>}
    {!busy&&<button type="button" className="m-update-close" aria-label="Позже" onClick={()=>appUpdate.dismiss()}>×</button>}
  </div>;
}

export function UpdateMenuItem(){
  const update=useUpdate();
  const label={checking:'Проверяем…',current:'Установлена последняя версия',offline:'Нет связи с сайтом',ready:'Есть новая версия',updating:'Обновляем…'}[update.status];
  return <div className="m-menu-update">
    <span>Версия {APP_VERSION}{label?` · ${label}`:''}</span>
    {update.status==='ready'?<button type="button" onClick={apply}>Обновить</button>:<button type="button" disabled={['checking','updating'].includes(update.status)} onClick={()=>appUpdate.check()}>Проверить обновления</button>}
  </div>;
}
