import React,{useState,useEffect} from 'react';
import CenteredModal,{SheetNav} from './CenteredModal.jsx';
import {ruleLanguage,ruleTranslation} from '../services/glossary.js';

export default function TranslationTemplates({templates,onChange,perform,busy,draft,onDraftChange,availableLanguages,folderControl}){
  const [error,setError]=useState('');useEffect(()=>setError(''),[draft?.id]);
  if(!draft)return null;
  const language=ruleLanguage(draft),update=patch=>{setError('');onDraftChange(current=>({...current,...patch}));};
  const save=event=>{event.preventDefault();setError('');const source=draft.source.trim(),translation=ruleTranslation(draft).trim(),context=(draft.context||'').trim();if(!source||!translation){setError('Введите слово и перевод.');return;}
    const previous=templates.find(entry=>entry.id===draft.id),sameSource=previous?.source?.trim().toLocaleLowerCase('ru')===source.toLocaleLowerCase('ru');
    if(templates.some(entry=>entry.kind!=='folder'&&entry.id!==draft.id&&ruleLanguage(entry)===language&&entry.source.trim().toLocaleLowerCase('ru')===source.toLocaleLowerCase('ru')&&(entry.context||'').trim()===context)){setError('Такой перевод уже есть. Измените существующий шаблон.');return;}
    const rule={...draft,source,language,translation,english:language==='en'?translation:undefined,aliases:sameSource?(previous.aliases||[]):[],context};
    perform(async()=>{if(await onChange(templates.some(entry=>entry.id===rule.id)?templates.map(entry=>entry.id===rule.id?rule:entry):[...templates,rule])!==false)onDraftChange(null);},'Перевод сохранён');
  };
  // On a phone the keyboard walks the fields with «Далее», and the language is a row of chips instead of a dropdown.
  const languages=availableLanguages.filter(entry=>entry.code!=='ru');
  return <CenteredModal label="Редактирование шаблона перевода" onClose={()=>onDraftChange(null)} className="m-template-dialog"><form inert={busy} onSubmit={save} noValidate>
    <SheetNav title="Перевод" onCancel={()=>onDraftChange(null)} disabled={busy}/><div className="m-modal-body">
      <label className="m-field">Слово<input autoFocus={!draft.source} maxLength={300} enterKeyHint="next" autoCapitalize="sentences" value={draft.source} onChange={event=>update({source:event.target.value})}/></label>
      <div className="m-field" role="radiogroup" aria-label="Язык">Язык<div className="m-language-chips">{languages.map(entry=><button type="button" role="radio" aria-checked={language===entry.code} key={entry.code} className={language===entry.code?'is-active':''} onClick={()=>update({language:entry.code})}>{entry.name}</button>)}</div></div>
      <label className="m-field">Перевод<input maxLength={300} enterKeyHint="next" autoCapitalize="off" value={ruleTranslation(draft)} onChange={event=>update({translation:event.target.value})}/></label>
      <label className="m-field">Контекст<textarea rows={2} maxLength={1000} value={draft.context||''} onChange={event=>update({context:event.target.value})} placeholder="Например, спортивный зал для тренировки футболистов"/></label>
      {folderControl}
      {error&&<p className="m-danger" role="alert">{error}</p>}
    </div>
  </form></CenteredModal>;
}
