import {FNL_TEAMS} from './fnl-teams.js';
export const TEAM_ROSTER_VERSION='fnl-2026-27';
const key=name=>String(name||'').toLocaleLowerCase('ru').replace(/[«»"\s-]/g,'');
export function mergeTeamRoster(existing){
  const names=new Set(existing.map(team=>key(team.name))),ids=new Set(existing.map(team=>team.id));
  return [...existing,...structuredClone(FNL_TEAMS).filter(team=>!ids.has(team.id)&&!names.has(key(team.name)))];
}
export async function initializeTeamRoster(storage){
  // A separate marker prevents deleted defaults from returning on every launch.
  if(storage.getItem('teamRosterVersion')===TEAM_ROSTER_VERSION)return;
  let teams;
  try{teams=JSON.parse(storage.getItem('teamTemplates')||'[]');}catch{return;}
  if(!Array.isArray(teams))return;
  await storage.setItems({teamTemplates:JSON.stringify(mergeTeamRoster(teams)),teamRosterVersion:TEAM_ROSTER_VERSION});
}
