async function request(action, input,notify=true) {
  try {
    const response = await fetch("/api/ai/" + action, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(input),
    });
    const body = await response.json();
    if (!response.ok) throw Object.assign(Error(body.error || "Ошибка Gemini"),{code:body.code});
    return body;
  } catch (error) {
    if(notify)window.dispatchEvent(
      new CustomEvent("schedule-error", { detail: error.message }),
    );
    throw error;
  }
}
export const parseScheduleFromText = (input) =>
  request("parseScheduleFromText", input);
export const translateText = (input) => request("translateText", input,false);
export const listModels = (input) => request('listModels',input,false);
