import {useEffect,useRef} from 'react';

// A drum under a mouse: dragging with the button held moves it like a finger, and on release it lands on a face
// (thrown a little further by a quick flick); each wheel notch turns it by exactly one face, a touchpad by one face per stretch of travel.
// Touch keeps the browser's own scrolling. A click that ended a drag never reaches the face under it.
// onDrag(): the drag has begun. onRelease(offset): where the drum would rest. onStep(direction): one face back (-1) or forward (1).
const NOTCH=50;
export default function useMouseDrum(root,{axis='x',onDrag,onRelease,onStep}){
  const latest=useRef(null);latest.current={onDrag,onRelease,onStep};
  useEffect(()=>{
    const node=root.current;if(!node)return;
    const scroll=axis==='x'?'scrollLeft':'scrollTop',at=event=>axis==='x'?event.clientX:event.clientY;
    let drag=null,travel=0,suppress=0;
    const down=event=>{if(event.pointerType!=='mouse'||event.button!==0)return;drag={id:event.pointerId,from:at(event),start:node[scroll],last:at(event),time:performance.now(),velocity:0,moved:false};};
    const move=event=>{
      if(!drag||event.pointerId!==drag.id)return;const offset=at(event)-drag.from;
      if(!drag.moved){if(Math.abs(offset)<5)return;drag.moved=true;try{node.setPointerCapture(event.pointerId);}catch{}node.style.scrollSnapType='none';latest.current.onDrag?.();}
      event.preventDefault();const now=performance.now();drag.velocity=(drag.last-at(event))/Math.max(1,now-drag.time);drag.last=at(event);drag.time=now;node[scroll]=drag.start-offset;
    };
    const up=event=>{
      if(!drag||event.pointerId!==drag.id)return;const done=drag;drag=null;if(!done.moved)return;
      try{node.releasePointerCapture(event.pointerId);}catch{}suppress=Date.now()+400;node.style.scrollSnapType='';
      const fling=performance.now()-done.time>100?0:Math.max(-2.5,Math.min(2.5,done.velocity))*160;
      latest.current.onRelease(node[scroll]+fling);
    };
    const cancel=()=>{if(!drag)return;const done=drag;drag=null;node.style.scrollSnapType='';if(done.moved)latest.current.onRelease(node[scroll]);};
    const wheel=event=>{
      if(event.ctrlKey)return;const raw=Math.abs(event.deltaX)>Math.abs(event.deltaY)?event.deltaX:event.deltaY;if(!raw)return;
      event.preventDefault();const delta=event.deltaMode===1?raw*33:event.deltaMode===2?raw*400:raw;
      // A mouse notch is one big step; a touchpad sends many small ones, which add up.
      if(Math.abs(delta)>=NOTCH){travel=0;latest.current.onStep(Math.sign(delta));return;}
      travel+=delta;if(Math.abs(travel)>=NOTCH){const direction=Math.sign(travel);travel=0;latest.current.onStep(direction);}
    };
    const click=event=>{if(Date.now()<suppress){event.preventDefault();event.stopPropagation();}};
    node.addEventListener('pointerdown',down);node.addEventListener('pointermove',move);node.addEventListener('pointerup',up);node.addEventListener('pointercancel',cancel);node.addEventListener('lostpointercapture',cancel);
    node.addEventListener('wheel',wheel,{passive:false});node.addEventListener('click',click,true);
    return()=>{node.removeEventListener('pointerdown',down);node.removeEventListener('pointermove',move);node.removeEventListener('pointerup',up);node.removeEventListener('pointercancel',cancel);node.removeEventListener('lostpointercapture',cancel);node.removeEventListener('wheel',wheel);node.removeEventListener('click',click,true);};
  },[axis]);
}
