import React,{useRef,useState} from 'react';
import EditorIcon from './EditorIcon.jsx';
import useScrollLock from './useScrollLock.js';

const standalone=()=>window.matchMedia?.('(display-mode: standalone)').matches||navigator.standalone===true;
const iOS=()=>/iP(hone|ad|od)/.test(navigator.userAgent)||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1;

// Safari on iPhone cannot put a page in full screen; a home-screen icon opens it without Safari's bars.
export function FullscreenItem(){
  const [help,setHelp]=useState(false);
  if(standalone())return null;
  const native=document.fullscreenEnabled&&!iOS();
  return <>
    <button type="button" className="m-menu-row" aria-expanded={native?undefined:help} onClick={()=>{if(!native){setHelp(value=>!value);return;}if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen().catch(()=>setHelp(true));}}>На весь экран<span className="m-menu-chevron" aria-hidden="true">›</span></button>
    {help&&<div className="m-menu-hint">
      <p>Safari на iPhone не даёт сайтам открываться на весь экран. Зато расписание можно поставить на экран «Домой» — с иконки оно откроется без панелей Safari.</p>
      <ol><li>Нажмите «Поделиться» (квадрат со стрелкой; если его не видно — сначала «⋯»).</li><li>Выберите «На экран „Домой“» и нажмите «Добавить».</li><li>Открывайте расписание с новой иконки.</li></ol>
      <p>У приложения с иконки свои данные, отдельно от Safari. Перенести их: здесь «Выгрузить данные», там «Загрузить данные».</p>
    </div>}
  </>;
}

// The menu rises from the bottom like an iOS sheet; drag its top edge down or tap outside to close.
export default function MenuSheet({onClose,children}){
  const sheet=useRef(null),drag=useRef(null);
  useScrollLock();
  const move=event=>{const current=drag.current;if(!current||event.pointerId!==current.id)return;current.dy=Math.max(0,event.clientY-current.y);sheet.current.style.transform=`translateY(${current.dy}px)`;};
  const end=()=>{const current=drag.current;drag.current=null;if(!current)return;sheet.current.style.transition='';if(current.dy>90)onClose();else sheet.current.style.transform='';};
  return <div className="m-menu-layer">
    <div className="m-layer-shade" onClick={onClose} aria-hidden="true"/>
    <aside ref={sheet} className="m-menu-sheet" role="dialog" aria-label="Настройки">
      <header className="m-menu-head" onPointerDown={event=>{if(event.target.closest('button'))return;drag.current={id:event.pointerId,y:event.clientY,dy:0};sheet.current.style.transition='none';event.currentTarget.setPointerCapture(event.pointerId);}} onPointerMove={move} onPointerUp={end} onPointerCancel={end}>
        <span className="m-menu-grabber" aria-hidden="true"/>
        <h1>Настройки</h1>
        <button type="button" className="m-icon-button" aria-label="Закрыть настройки" autoFocus onClick={onClose}><EditorIcon name="close"/></button>
      </header>
      <div className="m-menu-scroll">{children}</div>
    </aside>
  </div>;
}
