import {useRef,useState} from 'react';
import {createCollectionHistory} from '../services/collection-history.js';

export default function useCollectionHistory(items,persist){
  const latest=useRef({items,persist});latest.current={items,persist};
  const [status,setStatus]=useState({canUndo:false,canRedo:false,pending:false}),history=useRef(null);
  if(!history.current)history.current=createCollectionHistory({read:()=>latest.current.items,write:next=>latest.current.persist(next),notify:setStatus});
  return {...status,record:history.current.record,change:history.current.change,undo:history.current.undo,redo:history.current.redo};
}
