// History advances only after storage has accepted the snapshot.
export function createCollectionHistory({read,write,notify=()=>{}}){
  const past=[],future=[];let pending=false;
  const snapshot=()=>({canUndo:past.length>0,canRedo:future.length>0,pending});
  const run=async(next,accept)=>{
    if(pending)return false;
    pending=true;notify(snapshot());
    try{if(await write(structuredClone(next))===false)return false;accept();return true;}
    finally{pending=false;notify(snapshot());}
  };
  return {
    snapshot,
    record(before){past.push(structuredClone(before));if(past.length>100)past.shift();future.length=0;notify(snapshot());},
    change(next){
      if(pending)return Promise.resolve(false);
      const before=structuredClone(read());
      if(JSON.stringify(before)===JSON.stringify(next))return Promise.resolve(true);
      return run(next,()=>{past.push(before);if(past.length>100)past.shift();future.length=0;});
    },
    undo(){if(pending||!past.length)return Promise.resolve(false);const before=structuredClone(read());return run(past.at(-1),()=>{past.pop();future.push(before);});},
    redo(){if(pending||!future.length)return Promise.resolve(false);const before=structuredClone(read());return run(future.at(-1),()=>{future.pop();past.push(before);});},
  };
}
