import React,{useLayoutEffect,useRef,useState} from 'react';
import {hapticTick} from '../services/wheel.js';

const HOLD=420;

export default function SlidingTabs({items,value,onChange,className='',label,nav=false,onHold}){
  const root=useRef(null),highlight=useRef(null),placed=useRef(false),gesture=useRef(null),held=useRef(false),suppress=useRef(0),[metrics,setMetrics]=useState([]),[tracking,setTracking]=useState(false);
  const active=Math.max(0,items.findIndex(item=>item.value===value));
  useLayoutEffect(()=>{const node=root.current,measure=()=>setMetrics([...node.querySelectorAll(':scope>button')].map(button=>({left:button.offsetLeft,top:button.offsetTop,width:button.offsetWidth,height:button.offsetHeight}))),observer=new ResizeObserver(measure);observer.observe(node);measure();return()=>observer.disconnect();},[]);
  // The highlight glides on a CSS transition of its transform, which the compositor keeps running while the next page renders.
  const place=rect=>{const node=highlight.current;if(!node||!rect)return;node.style.width=rect.width+'px';node.style.height=rect.height+'px';node.style.top=rect.top+'px';node.style.transform=`translate3d(${rect.left}px,0,0)`;};
  useLayoutEffect(()=>{const node=highlight.current,rect=metrics[active];if(tracking||!node||!rect)return;if(placed.current){place(rect);return;}node.style.transition='none';place(rect);node.getBoundingClientRect();node.style.transition='';placed.current=true;},[active,metrics,tracking]);
  const nearest=x=>metrics.reduce((best,rect,index)=>Math.abs(rect.left+rect.width/2-x)<Math.abs(metrics[best].left+metrics[best].width/2-x)?index:best,0);
  const cancelHold=()=>{clearTimeout(gesture.current?.timer);};
  const stop=(event,commit)=>{const current=gesture.current;gesture.current=null;if(!current)return;clearTimeout(current.timer);if(!current.moved)return;try{root.current.releasePointerCapture(current.pointerId);}catch{}suppress.current=Date.now()+400;setTracking(false);const rect=root.current.getBoundingClientRect();if(commit&&event.clientY>=rect.top-12&&event.clientY<=rect.bottom+12)onChange(items[nearest(event.clientX-rect.left)].value);};
  // Holding a tab, as in Telegram, opens that tab's own menu instead of switching to it; a tab without one returns false.
  const hold=(button,pointerId)=>{const item=items[[...root.current.querySelectorAll(':scope>button')].indexOf(button)];if(!item||onHold(item.value,button.getBoundingClientRect(),pointerId)===false)return;held.current=true;hapticTick();};
  const Tag=nav?'nav':'div';
  return <Tag ref={root} className={`m-sliding-tabs ${tracking?'is-tracking':''} ${className}`} aria-label={label} role={nav?undefined:'tablist'}
    onPointerDown={event=>{held.current=false;if(!metrics.length||event.isPrimary===false||event.button!==0)return;const button=event.target.closest('button'),pointerId=event.pointerId;gesture.current={pointerId,startX:event.clientX,startY:event.clientY,moved:false,timer:onHold&&button?setTimeout(()=>{if(gesture.current?.moved)return;hold(button,pointerId);},HOLD):null};}}
    onPointerMove={event=>{const current=gesture.current;if(!current||event.pointerId!==current.pointerId||held.current)return;if(Math.hypot(event.clientX-current.startX,event.clientY-current.startY)>8)cancelHold();if(Math.abs(event.clientX-current.startX)<6&&!current.moved)return;current.moved=true;root.current.setPointerCapture(event.pointerId);event.preventDefault();if(!tracking)setTracking(true);const x=event.clientX-root.current.getBoundingClientRect().left,near=metrics[nearest(x)],first=metrics[0],last=metrics.at(-1);place({...near,left:Math.max(first.left,Math.min(last.left+last.width-near.width,x-near.width/2))});}}
    onPointerUp={event=>stop(event,!held.current)} onPointerCancel={event=>stop(event,false)}
    onContextMenu={event=>{if(!onHold)return;event.preventDefault();const button=event.target.closest('button');if(button&&!(held.current&&gesture.current)){cancelHold();hold(button,null);}}}>
    {metrics.length>0&&<span ref={highlight} className="m-tab-highlight" aria-hidden="true"/>}
    {items.map((item,index)=><button type="button" key={item.value} role={nav?undefined:'tab'} aria-current={nav&&active===index?'page':undefined} aria-selected={nav?undefined:active===index} aria-haspopup={onHold?'menu':undefined}
      onClick={event=>{const swallow=held.current&&event.detail!==0;held.current=false;if(swallow)return;if(event.detail===0||Date.now()>=suppress.current)onChange(item.value);}}
      onKeyDown={event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?items.length-1:Math.max(0,Math.min(items.length-1,index+(event.key==='ArrowLeft'?-1:1)));onChange(items[next].value);root.current.querySelectorAll(':scope>button')[next].focus();}}
    >{item.content||item.label}</button>)}
  </Tag>;
}
