import React,{useState} from 'react';
import CenteredModal from './CenteredModal.jsx';
import FolderSelect from './FolderSelect.jsx';
import EditorIcon from './EditorIcon.jsx';
import {folderContents,isFolder} from '../services/template-folders.js';
import {eventLabel,eventTime,EVENT_COLORS} from '../services/editor.js';

// Opened for one step (save or load) it starts there, and «Назад» from that step closes it.
export default function SaveEventTemplate({item,entries,Icon,onSave,onLoad,onClose,busy,perform,initialMode=null}){
  const [mode,setMode]=useState(initialMode),[parentId,setParentId]=useState(null),folder=entries.find(entry=>entry.id===parentId&&isFolder(entry));
  const save=event=>{event.preventDefault();perform(async()=>{if(await onSave(item,parentId)!==false)onClose();},'Событие сохранено в шаблоны');};
  const back=()=>{if(mode==='load'&&folder)setParentId(folder.parentId||null);else if(initialMode)onClose();else{setMode(null);setParentId(null);}};
  return <CenteredModal label="Шаблоны события" onClose={onClose} className="m-template-dialog m-scale-dialog m-template-browser"><header className="m-scale-heading">{mode&&<button type="button" className="m-icon-button" aria-label="Назад" onClick={back}><EditorIcon name="back"/></button>}<h2>{folder?.name||'Шаблоны события'}</h2><button type="button" className="m-icon-button" aria-label="Закрыть шаблоны события" onClick={onClose}><EditorIcon name="close"/></button></header>
    {!mode?<div className="m-modal-body"><button type="button" className="m-template-select" onClick={()=>setMode('save')}><EditorIcon name="bookmark"/>Сохранить шаблон</button><button type="button" className="m-template-select" onClick={()=>setMode('load')}><EditorIcon name="folder"/>Загрузить шаблон</button></div>:mode==='save'?<form onSubmit={save}><div className="m-modal-body"><p>{eventLabel(item)}</p><FolderSelect entries={entries} value={parentId} onChange={setParentId}/></div><div className="m-modal-footer"><button className="m-primary" disabled={busy}>Сохранить</button></div></form>:<div className="m-modal-body">{folderContents(entries,folder?.id||null).length===0&&<p className="m-empty-day">Нет шаблонов</p>}{folderContents(entries,folder?.id||null).map(entry=><button type="button" key={entry.id} className="m-template-select" style={!isFolder(entry)?{background:EVENT_COLORS[entry.color]?.[1]||'#fff'}:undefined} onClick={()=>{if(isFolder(entry)){setParentId(entry.id);return;}onLoad(entry);onClose();}}>{isFolder(entry)?<EditorIcon name="folder"/>:entry.type!=='game'?<Icon icon={entry.icon===undefined?'football-field':entry.icon}/>:null}<span>{isFolder(entry)?entry.name:eventLabel(entry)}{!isFolder(entry)&&<small>{eventTime(entry)}</small>}</span></button>)}</div>}
  </CenteredModal>;
}
