import React from 'react';
import {EVENT_COLORS,eventLabel} from '../services/editor.js';
import GestureList from './GestureList.jsx';
import QuickEventTime from './QuickEventTime.jsx';
import InlineCard,{RowTab} from './InlineCard.jsx';
import {GameLine} from './GameMatch.jsx';

// A schedule card swiped left uncovers «Новое справа» and «Удалить», swiped right «Копировать» and «Новое слева».
const SWIPE={end:['right','delete'],start:['copy','left']};

export default function EventList({items,Icon,onEdit,onTime,onMove,onPlace,onHold,onSwipe,enabled=true,inline=null}){
  return <GestureList items={items} enabled={enabled&&!inline?.textId} onMove={onMove} onPlace={onPlace} onHold={onHold} swipeActions={onPlace&&SWIPE} tab={item=><RowTab item={item} Icon={Icon}/>} onSwipe={onSwipe} className="m-list">{(item,handle)=>inline?<InlineCard item={item} items={items} editingText={inline.textId===item.id} onPatch={patch=>inline.onPatch(item.id,patch)} onBeginEdit={inline.onBeginEdit} onText={()=>inline.onText(item.id)} onTextDone={inline.onTextDone} Icon={Icon} iconNames={inline.iconNames} languages={inline.languages} availableLanguages={inline.availableLanguages} teams={inline.teams} handle={handle}/>:<article data-type={item.type} className="m-card" style={{'--event-fill':EVENT_COLORS[item.color]?.[1]||'#fff'}}><div className="m-row"><QuickEventTime item={item} Icon={Icon} onOpen={()=>onEdit(item.id,'icon')} onTime={field=>onTime(item.id,field)}/><button type="button" className="m-event-open" aria-label={`Редактировать: ${eventLabel(item)}`} aria-keyshortcuts="ArrowUp ArrowDown" onClick={()=>onEdit(item.id,item.type==='game'?'teams':'text')}>{item.type==='game'?<span className="m-event-description m-game-line"><GameLine item={item}/>{item.description&&<small>{item.description}</small>}</span>:<span className="m-event-description">{item.description||<span className="m-placeholder">Новое событие</span>}</span>}</button>{handle}</div></article>}</GestureList>;
}
