import React,{useEffect,useState} from 'react';
import {createPortal} from 'react-dom';

// Printing the page should give the finished schedule picture, not the editor around it.
export default function PrintImage({blob}){
  const [url,setUrl]=useState(null);
  useEffect(()=>{if(!blob){setUrl(null);return;}const next=URL.createObjectURL(blob);setUrl(next);return()=>URL.revokeObjectURL(next);},[blob]);
  return url?createPortal(<img className="m-print-image" src={url} alt=""/>,document.body):null;
}
