import React,{useEffect,useRef} from 'react';
import useScrollLock from './useScrollLock.js';
import useBackClose from './useBackClose.js';

const phone=()=>matchMedia('(max-width:600px)').matches;

// On a phone the window is a sheet from the bottom: pulled down by its grabber or title, it follows the finger and closes once pulled far or fast enough.
export default function CenteredModal({label,onClose,className='',children,...props}){
  const close=useRef(onClose);close.current=onClose;
  const layer=useRef(null),sheet=useRef(null),pull=useRef(null);
  useScrollLock();useBackClose(()=>close.current());
  useEffect(()=>{const focus=document.activeElement;const escape=event=>{if(event.key==='Escape'&&!document.querySelector('dialog[open]')){event.stopPropagation();close.current();}};document.addEventListener('keydown',escape);return()=>{document.removeEventListener('keydown',escape);if(focus?.isConnected)focus.focus({preventScroll:true});};},[]);
  // The on-screen keyboard covers the bottom of the screen on iPhone; the sheet rises above it.
  useEffect(()=>{const view=window.visualViewport;if(!view)return;const fit=()=>{if(layer.current)layer.current.style.paddingBottom=`${Math.max(0,window.innerHeight-view.height-view.offsetTop)}px`;};fit();view.addEventListener('resize',fit);view.addEventListener('scroll',fit);return()=>{view.removeEventListener('resize',fit);view.removeEventListener('scroll',fit);};},[]);
  const move=(offset,animate)=>{const node=sheet.current;if(!node)return;node.style.transition=animate?'transform 200ms ease':'none';node.style.transform=offset?`translateY(${offset}px)`:'';layer.current.style.setProperty('--m-pull',String(Math.max(0,1-offset/(node.offsetHeight||1))));};
  const down=event=>{if(!phone()||event.button>0||!event.target.closest('[data-sheet-grab], h2')||event.target.closest('button, input, textarea, select'))return;pull.current={id:event.pointerId,y:event.clientY,offset:0,at:performance.now(),speed:0};event.currentTarget.setPointerCapture?.(event.pointerId);};
  const drag=event=>{const at=pull.current;if(!at||event.pointerId!==at.id)return;const offset=Math.max(0,event.clientY-at.y),now=performance.now();at.speed=(offset-at.offset)/Math.max(1,now-at.at);at.offset=offset;at.at=now;move(offset,false);};
  const up=event=>{const at=pull.current;if(!at||event.pointerId!==at.id)return;pull.current=null;if(at.offset>110||at.speed>.6){move(sheet.current.offsetHeight,true);setTimeout(()=>close.current(),180);}else move(0,true);};
  return <div ref={layer} className="m-event-layer"><div className="m-layer-shade" onClick={()=>close.current()} aria-hidden="true"/><section ref={sheet} role="dialog" aria-label={label} className={`m-centered-dialog ${className}`} onPointerDown={down} onPointerMove={drag} onPointerUp={up} onPointerCancel={up} {...props}><div className="m-sheet-grab" data-sheet-grab aria-hidden="true"/>{children}</section></div>;
}

// The bar across the top of a sheet, as on iOS: «Отмена» on the left, the title in the middle, the main action in bold on the right
// (a form's submit unless onAction is given; none for a sheet that only lists choices). Pulling the bar down closes the sheet.
export function SheetNav({title,onCancel,action='Сохранить',onAction,disabled=false}){
  return <header className="m-sheet-nav" data-sheet-grab><button type="button" className="m-sheet-nav-cancel" onClick={onCancel}>Отмена</button><h2>{title}</h2>{action?<button type={onAction?'button':'submit'} className="m-sheet-nav-main" disabled={disabled} onClick={onAction}>{action}</button>:<span aria-hidden="true"/>}</header>;
}
