// Dimensions are output pixels. Rendering uses a 2× pixel ratio.
export const validImageSize=value=>value&&typeof value.name==='string'&&Number.isInteger(value.width)&&Number.isInteger(value.height)&&value.width>=320&&value.width<=7680&&value.height>=320&&value.height<=7680;
export const logicalWidth=value=>Math.max(160,Math.min(3840,Number(value)||896));
export function applyImageSize(state,preset){return {...state,exportWidth:preset.width/2,exportHeight:preset.height/2};}
export function resizeImageWidth(state,pixels){const width=logicalWidth(pixels/2);return {...state,exportWidth:width,exportHeight:state.exportHeight?Math.round(state.exportHeight*width/logicalWidth(state.exportWidth)*2)/2:null};}
// Height alone: null goes back to the content's own height.
export function resizeImageHeight(state,pixels){return {...state,exportHeight:pixels==null?null:Math.max(160,Math.min(3840,Math.round(Number(pixels))/2))};}
export function defaultImageSizes(){
  const devices=[['A4 · 300 ppi',2480,3508],['iPhone 17',1206,2622],['iPad Air 11″',1640,2360],['Android · Full HD+',1080,2400],['Full HD',1080,1920],['4K',2160,3840]];
  return ['day','week'].flatMap(mode=>{const parentId=`sizes-${mode}`;return [{id:parentId,kind:'folder',name:mode==='day'?'Дни':'Недели',parentId:null},...devices.map(([name,width,height],index)=>({id:`${parentId}-${index}`,name,width:mode==='day'?width:height,height:mode==='day'?height:width,parentId}))];});
}
export async function initializeImageSizes(storage){if(storage.getItem('imageSizesVersion'))return;const current=JSON.parse(storage.getItem('sizeTemplates')||'[]');await storage.setItems({sizeTemplates:JSON.stringify([...current,...defaultImageSizes()]),imageSizesVersion:'1'});}
