import React from 'react';
import {EVENT_COLORS,localDate} from '../services/editor.js';

// Pieces the finished pictures, day and week, share: event colours, translations and how dates read.

// Each event colour as a strong accent for a thin bar and as a soft tint for the background behind the event.
const ACCENTS={red:'#c4473f',orange:'#d27a2c',yellow:'#c49a1a',green:'#3d8a52',blue:'#3b78c0',purple:'#7a5ac0',gray:'#7b8189'};
const mix=(hex,amount)=>{const value=parseInt(hex.slice(1),16),channel=shift=>Math.round(((value>>shift)&255)*amount+255*(1-amount));return `rgb(${channel(16)},${channel(8)},${channel(0)})`;};
export function eventPaint(color){
  if(!EVENT_COLORS[color])return null;
  return {'--x-accent':ACCENTS[color],'--x-tint':mix(EVENT_COLORS[color][1],.6)};
}

export function translationsOf(item,languages){return languages.map(code=>item.translations?.[code]).filter(Boolean);}
// Inline translations follow the text in grey; any other mode puts each on its own line under it.
export function Translations({item,languages,mode,className=''}){
  const lines=translationsOf(item,languages);if(!lines.length||mode==='text-block')return null;
  return mode==='inline'?<span className={`x-tr is-inline ${className}`}>{lines.join(' / ')}</span>:<span className={`x-tr ${className}`}>{lines.map((line,index)=><span key={index}>{line}</span>)}</span>;
}

const format=(day,options)=>new Intl.DateTimeFormat('ru-RU',options).format(new Date(`${day}T12:00:00`));
// «26 октября», or «26–28 октября» and «30 октября – 2 ноября» for a span; the weekday line below it says «понедельник» or «пн – ср».
export function dateWords(start,end){
  if(!end||end<=start)return {main:format(start,{day:'numeric',month:'long'}),weekday:format(start,{weekday:'long'})};
  const sameMonth=start.slice(0,7)===end.slice(0,7);
  return {main:sameMonth?`${format(start,{day:'numeric'})}–${format(end,{day:'numeric',month:'long'})}`:`${format(start,{day:'numeric',month:'long'})} – ${format(end,{day:'numeric',month:'long'})}`,weekday:`${format(start,{weekday:'short'})} – ${format(end,{weekday:'short'})}`};
}
export function weekWords(start,end){
  const year=end.slice(0,4),sameYear=start.slice(0,4)===year;
  return `${format(start,{day:'numeric',month:'long',...(sameYear?{}:{year:'numeric'})})} — ${format(end,{day:'numeric',month:'long'})} ${year}`;
}
export const itemDay=item=>localDate(item.date);

export {softHyphens} from '../services/hyphens.js';
