import React,{useState} from 'react';
import CenteredModal from './CenteredModal.jsx';
import FolderSelect from './FolderSelect.jsx';
import EditorIcon from './EditorIcon.jsx';
import {folderContents,isFolder} from '../services/template-folders.js';
import {validImageSize} from '../services/image-sizes.js';

export default function ScaleTemplateMenu({entries,weekly,width,height,onChange,onApply,onClose,perform,busy}){
  const initialFolder=entries.find(entry=>entry.id===(weekly?'sizes-week':'sizes-day')&&isFolder(entry))?.id||null;
  const [stage,setStage]=useState('choice'),[parentId,setParentId]=useState(initialFolder),[error,setError]=useState(''),[draft,setDraft]=useState({name:`${width} × ${height}`,width,height});
  const folder=entries.find(entry=>entry.id===parentId&&isFolder(entry));

  const save=event=>{event.preventDefault();setError('');const value={...draft,name:draft.name.trim(),id:crypto.randomUUID(),parentId};if(!value.name||!validImageSize(value)){setError('Укажите название, ширину и высоту от 320 до 7680 px.');return;}perform(async()=>{if(await onChange([...entries,value])!==false)onClose();},'Шаблон масштаба сохранён');};
  const back=()=>{setError('');if(stage==='choose'&&folder)setParentId(folder.parentId||null);else setStage('choice');};
  return <CenteredModal label="Шаблон масштаба" onClose={onClose} className="m-template-dialog m-scale-dialog">
    <header className="m-scale-heading">{stage!=='choice'&&<button type="button" className="m-icon-button" aria-label="Назад" onClick={back}><EditorIcon name="back"/></button>}<h2>{stage==='choice'?'Шаблон':stage==='save'?'Сохранить масштаб':folder?.name||'Выбрать масштаб'}</h2><button type="button" className="m-icon-button" aria-label="Закрыть шаблон масштаба" onClick={onClose}><EditorIcon name="close"/></button></header>
    {stage==='choice'?<div className="m-modal-body"><button type="button" className="m-template-select" onClick={()=>setStage('choose')}><EditorIcon name="folder"/>Выбрать</button><button type="button" className="m-template-select" onClick={()=>setStage('save')}><EditorIcon name="bookmark"/>Сохранить</button></div>:stage==='save'?<form onSubmit={save}>
      <div className="m-modal-body"><label className="m-field">Название<input autoFocus required maxLength={100} value={draft.name} onChange={event=>setDraft(current=>({...current,name:event.target.value}))}/></label><div className="m-size-fields">{[['width','Ширина'],['height','Высота']].map(([key,label])=><label key={key} className="m-field">{label}, px<input type="number" required min={320} max={7680} step={1} value={draft[key]} onChange={event=>setDraft(current=>({...current,[key]:Number(event.target.value)}))}/></label>)}</div><FolderSelect entries={entries} value={parentId} onChange={setParentId}/>{error&&<p role="alert" className="m-danger">{error}</p>}</div><div className="m-modal-footer"><button className="m-primary" disabled={busy}>Сохранить</button></div>
    </form>:<div className="m-modal-body">{folderContents(entries,folder?.id||null).map(entry=><button type="button" key={entry.id} className="m-template-select" onClick={()=>isFolder(entry)?setParentId(entry.id):onApply(entry)}><EditorIcon name={isFolder(entry)?'folder':'image'}/><span>{entry.name}{!isFolder(entry)&&<small>{entry.width} × {entry.height} px</small>}</span></button>)}</div>}
  </CenteredModal>;
}
