import React from 'react';

// An empty schedule says so in the middle, so it never looks unloaded, and offers quiet ways to fill it: a template, or (in a week) a day off.
// An empty day off says «Выходной» in the same place, and its chips stay where they were, so switching moves nothing.
export default function EmptyDay({off=false,onLoad,onOff}){
  return <div className={`m-empty-day ${off?'is-off':''}`}><p>{off?'Выходной':'Нет событий'}</p>{(onLoad||onOff)&&<div className="m-empty-actions">{onLoad&&<button type="button" className="m-empty-load" onClick={onLoad}>Загрузить шаблон</button>}{onOff&&<button type="button" className="m-empty-load" onClick={onOff}>{off?'Сделать рабочим':'Сделать выходным'}</button>}</div>}</div>;
}
