import {ruleLanguage,ruleTranslation} from './glossary.js';
const PREVIOUS_TRANSLATION_CONTEXT='Расписание футбольной команды: тренировки, матчи, анализ игры, сборы, экипировка и восстановление. Использовать футбольные термины. Зал для тренировки — gym, помещение для теории или конференции — room.';
export const DEFAULT_TRANSLATION_CONTEXT='Расписание футбольной команды: тренировки, матчи, анализ игры, сборы, экипировка и восстановление. Использовать футбольные термины и сохранять конкретику названий. Тренировочный зал — gym; конференц-зал — conference room; обычное помещение для теории — room; зал ожидания — waiting lounge. Название конкретного помещения сохранять полностью в переводе.';
const seed=[
  ['Зал','Gym',['зала','залу','залом','зале','залы','залов','залам','залами','залах'],'Спортивный или тренажёрный зал. Обычное помещение для теории — room; конференц-зал — conference room; зал ожидания — waiting lounge.'],
  ['Активация','Activation',['активации','активацию'],'Подготовка футболистов к нагрузке.'],
  ['В зале для','in the room for',[],'Помещение для теории, собрания или анализа.'],
  ['В конференц-зале','in the conference room',['в конференц зале','в конференц–зале','в конференц‑зале'],'В конкретном конференц-зале для собраний и анализа. Сохранять conference room полностью.'],
  ['Конференц-зал','conference room',['конференц-зала','конференц-залу','конференц-зале','конференц-залом','конференц зал','конференц зале','конференц зала','конференц–зал','конференц‑зал'],'Конкретное название помещения — conference room, а не общее room.'],
  ['В трен. зале','in the gym',['в трен.зале','в тренировочном зале','в тренажёрном зале','в тренажерном зале'],'Спортивный зал для физической подготовки.'],
  ['Тихий час','Rest time',['отбой'],'Время отдыха команды.'],
  ['Сбор','Gathering',['сбор на базе','сбора','сбору'],'Сбор игроков в указанном месте; тренировочный сбор переводить по контексту как training camp.'],
  ['Парадная форма','everyday tracksuit',['парадной формы','парадную форму','парадной форме'],'Повседневный командный спортивный костюм.'],
  ['Тренировочная форма','training gear',['тренировочной формы','тренировочную форму','тренировочной форме'],'Экипировка для тренировки.'],
  ['Щитки','Shin pads',['щитков','щитками','щитках'],'Футбольная защита голени.'],
  ['Поле','Pitch',['поля','полю','полем'],'Футбольное поле.'],
  ['Теория','Analysis',['теории','теорию'],'Анализ игры и тактики футбольной команды.'],
  ['Тренировка','training',['тренировки','тренировку','тренировке'],'Футбольная тренировка.'],
  ['Выходной','Day off',['выходного','выходным'],'День отдыха команды.'],
];
export const footballGlossary=()=>seed.map(([source,translation,aliases,context],index)=>({id:`football-rule-${index}`,source,translation,english:translation,language:'en',aliases,context,enabled:true}));
export function seedFootballGlossary(current){current=current.map(rule=>rule.id==='football-gym'&&rule.english==='gym'&&!rule.translation?{...rule,language:'en',english:'Gym',translation:'Gym'}:rule);const normalized=text=>text.toLocaleLowerCase('ru').replaceAll('ё','е');const existing=new Set(current.filter(rule=>rule.kind!=='folder'&&ruleLanguage(rule)==='en').map(rule=>normalized(rule.source)));return [...current,...footballGlossary().filter(rule=>!existing.has(normalized(rule.source)))];}
export function upgradeFootballGlossary(current){
  const defaults=footballGlossary();
  return current.map(rule=>{
    if(ruleLanguage(rule)!=='en')return rule;
    const replacement=defaults.find(entry=>entry.id===rule.id&&entry.source===rule.source);
    const previous=rule.id==='football-rule-3'?'in the room':rule.id==='football-rule-4'?'room':null;
    if(replacement&&previous&&ruleTranslation(rule)===previous)return {...rule,translation:replacement.translation,english:replacement.translation,aliases:[...new Set([...(rule.aliases||[]),...replacement.aliases])],context:rule.context==='Помещение для теории и собраний.'?replacement.context:rule.context};
    if(replacement&&rule.id==='football-rule-0'&&rule.context==='Спортивный или тренажёрный зал. Для теории и конференции использовать room.')return {...rule,context:replacement.context};
    return rule;
  });
}
export async function initializeFootballGlossary(storage){
  const version=storage.getItem('footballGlossaryVersion');if(version==='2')return;
  const current=JSON.parse(storage.getItem('translationTemplates')||'[]'),changes={translationTemplates:JSON.stringify(version?upgradeFootballGlossary(current):seedFootballGlossary(current)),footballGlossaryVersion:'2'};
  const context=storage.getItem('translationContext');
  try{if(context&&JSON.parse(context)===PREVIOUS_TRANSLATION_CONTEXT)changes.translationContext=JSON.stringify(DEFAULT_TRANSLATION_CONTEXT);}catch{}
  await storage.setItems(changes);
}
