import React from 'react';
import {calendarWeeks} from '../services/week.js';
import {eventTime,pictureStyle} from '../services/editor.js';
import {sideBySide} from './ExportRows.jsx';
import {Translations,dateWords,eventPaint,itemDay,softHyphens,weekWords} from './ResultParts.jsx';
import './result.css';

// The finished picture of a week: seven equal columns of equal cards. Each event is the same strip as in a day,
// its time on one line above the text with the icon at the right; a day off is green and says so under its date.
const WEEKDAYS=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];
// A narrow column fits «10:30–12:00» only without the spaces around the dash.
const shortTime=item=>eventTime(item).replace(' – ','–');
function Event({item,Icon,languages,mode}){
  const words=<Translations item={item} languages={languages} mode={mode}/>;
  switch(item.type){
    case 'h1':case 'h2':case 'h3':return <div data-type={item.type} className={`x-cell-title is-${item.type}`}><span>{softHyphens(item.description)}</span>{words}</div>;
    case 'comment':return <div data-type="comment" className="x-cell-note"><span>{softHyphens(item.description)}</span>{words}</div>;
    case 'date':return <div data-type="date" className="x-cell-note">{item.date&&dateWords(itemDay(item),item.endDate).main}{item.description&&<> · {item.description}</>}{words}</div>;
    case 'image':return <div data-type="image" className="x-cell-picture">{item.image&&<img src={item.image} alt="" style={pictureStyle(item)}/>}</div>;
    case 'game':return <div data-type="game" className="x-cev" style={eventPaint(item.color)||undefined}>
      {eventTime(item)&&<b className="x-cev-time">{shortTime(item)}</b>}
      {['homeTeam','awayTeam'].map((key,index)=><span key={key} className="x-cev-team">{item[key]?.image&&<img src={item[key].image} alt="" draggable={false}/>}<span>{softHyphens(item[key]?.name||`Команда ${index+1}`)}</span></span>)}
      {item.description&&<span className="x-cev-place">{softHyphens(item.description)}</span>}{words}
    </div>;
    default:return <div data-type={item.type} className="x-cev" style={eventPaint(item.color)||undefined}>
      {(eventTime(item)||item.icon)&&<b className="x-cev-time"><span>{shortTime(item)}</span>{item.icon&&<Icon icon={item.icon}/>}</b>}
      <span className="x-cev-text">{softHyphens(item.description)}</span>{words}
    </div>;
  }
}

export default function WeeklyPreview({state,Icon,languages=[],translationMode='inline'}){
  return <div className="x-sheet x-week" lang="ru">
    <header className="x-week-head"><h1>{state.cardTitle}</h1><p>{weekWords(state.weekStart,state.weekEnd)}</p></header>
    <div className="x-week-grid">
      {WEEKDAYS.map((name,index)=><strong key={name} className={`x-weekday ${index>4?'is-weekend':''}`}>{name}</strong>)}
      {calendarWeeks(state.weekStart,state.weekEnd).flat().map((day,index)=>{
        if(!day)return <section key={`empty-${index}`} className="x-cell is-outside"/>;
        const items=state.schedule.filter(item=>item.dayKey===day),off=!!state.offDays?.[day],date=new Date(`${day}T12:00:00`);
        return <section key={day} className={`x-cell ${off?'is-off':''} ${items.length?'':'is-empty'}`}>
          <header className="x-cell-head"><b>{date.getDate()}</b><small>{date.toLocaleDateString('ru-RU',{month:'short'}).replace('.','')}</small></header>
          {off&&<span className="x-cell-off">Выходной</span>}
          {sideBySide(items,items.map(item=><Event key={item.id} item={item} Icon={Icon} languages={languages} mode={translationMode}/>))}
        </section>;
      })}
    </div>
  </div>;
}
