import React,{useEffect,useRef} from 'react';
import useScrollLock from './useScrollLock.js';
import useBackClose from './useBackClose.js';

// A question before something is removed. Plain: «Отмена» and «Удалить».
// With choices (deleting an event of a group): one button per answer, the strongest last, then «Отмена».
export default function ConfirmDialog({request,onClose}){
  const ref=useRef(null);useScrollLock();useBackClose(onClose);
  useEffect(()=>{ref.current.showModal();return()=>ref.current?.close();},[]);
  const run=async action=>{if(await action()!==false)onClose();};
  return <dialog ref={ref} className="m-confirm" onCancel={onClose} onClick={event=>{if(event.target===ref.current)onClose();}} aria-labelledby="m-confirm-title"><h2 id="m-confirm-title">{request.title}</h2>{request.detail&&<p>{request.detail}</p>}
    {request.choices
      ?<div className="m-confirm-actions is-choices">{request.choices.map(choice=><button key={choice.label} type="button" className={choice.danger?'m-danger-fill':''} onClick={()=>run(choice.action)}>{choice.label}</button>)}<button autoFocus type="button" onClick={onClose}>Отмена</button></div>
      :<div className="m-confirm-actions"><button autoFocus type="button" onClick={onClose}>Отмена</button><button type="button" className="m-danger-fill" onClick={()=>run(request.action)}>Удалить</button></div>}
  </dialog>;
}

// Asked when an event of a group is deleted or copied: only that event, or the whole group.
export function groupRequest(kind,size,{one,all}){
  const remove=kind==='delete';
  return {title:remove?'Удалить событие из группы?':'Скопировать событие из группы?',detail:`В группе ${size} ${size<5?'события':'событий'}.${remove?'':' Одно событие встанет копией в ту же группу, вся группа — новой группой под ней.'}`,choices:[{label:'Только это событие',action:one},{label:'Всю группу',danger:remove,action:all}]};
}
