import React from 'react';
import {eventTime,pictureStyle} from '../services/editor.js';
import {sideBySide} from './ExportRows.jsx';
import {scheduleRows} from '../services/rows.js';
import './result.css';
import {Translations,dateWords,eventPaint,itemDay} from './ResultParts.jsx';

// The finished picture of a day: a title line, then the day as a quiet column of times and events.
// Every event is a strip of the same width and height; only its colour changes.
// One line in a column of fixed width, so every description starts at the same place.
function Time({item}){return <span className="x-time">{eventTime(item)}</span>;}
function Team({team,fallback}){return <span className="x-team">{team?.image&&<img src={team.image} alt="" draggable={false}/>}<span>{team?.name||fallback}</span></span>;}

function Block({item,Icon,languages,mode,head=false}){
  const words=<Translations item={item} languages={languages} mode={mode}/>;
  switch(item.type){
    case 'h1':return <h1 data-type="h1" className="x-h1"><span>{item.description}</span>{words}</h1>;
    case 'h2':return <h2 data-type="h2" className="x-h2"><span>{item.description}</span>{words}</h2>;
    case 'h3':return <h3 data-type="h3" className="x-h3"><span>{item.description}</span>{words}</h3>;
    case 'date':{
      if(!item.date)return <div data-type="date"/>;
      const {main,weekday}=dateWords(itemDay(item),item.endDate);
      return <div data-type="date" className="x-date"><strong>{main}</strong>{head?item.description&&<small>{item.description}</small>:<small>{weekday}{item.description&&<> · {item.description}</>}</small>}{words}</div>;
    }
    case 'image':return <div data-type="image" className="x-picture">{item.image&&<img src={item.image} alt="" style={pictureStyle(item)}/>}</div>;
    case 'comment':return <p data-type="comment" className="x-note"><span>{item.description}</span>{words}</p>;
    case 'game':return <div data-type="game" className="x-event x-game" style={eventPaint(item.color)||undefined}>
      <Time item={item}/>
      <span className="x-icon">{item.icon&&<Icon icon={item.icon}/>}</span>
      <div className="x-game-body"><div className="x-game-teams"><Team team={item.homeTeam} fallback="Команда 1"/><span className="x-versus">—</span><Team team={item.awayTeam} fallback="Команда 2"/></div>{item.description&&<span className="x-game-place">{item.description}</span>}{words}</div>
    </div>;
    default:return <div data-type={item.type} className={`x-event ${item.color?'is-colored':''}`} style={eventPaint(item.color)||undefined}>
      <Time item={item}/>
      <span className="x-icon">{item.icon&&<Icon icon={item.icon}/>}</span>
      <span className="x-text"><span>{item.description}</span>{words}</span>
    </div>;
  }
}

// A first group that holds the title or the date is the header: it reads as one line («Расписание на 26 октября»), the picture at its right.
export default function DayPreview({items,Icon,languages=[],translationMode='inline'}){
  const first=scheduleRows(items)[0]||[],head=first.some(item=>['h1','date'].includes(item.type))?first:[],rest=items.slice(head.length);
    const block=(item,inHead)=><Block key={item.id} item={item} Icon={Icon} languages={languages} mode={translationMode} head={inHead}/>;
  return <div className="x-sheet x-day">{head.length>0&&<header className="x-head"><div className="x-head-line">{head.map(item=>block(item,true))}</div></header>}{sideBySide(rest,rest.map(item=>block(item,false)))}</div>;
}
